def test_local_addition_is_visible_and_version_unknown(self):
 with tempfile.TemporaryDirectory() as td:
  db=self.fixture(pathlib.Path(td));doc=self.doc(db,'aidl:a.I#take(P)');doc.update(canonical_signature='aidl:a.I#added(int)',name='added',origin='local',overlay_revision=1);doc['entry_id']=hashlib.sha256(doc['canonical_signature'].encode()).hexdigest();doc['arguments']=[{'text':'int','status':'primitive','codec_status':'unknown'}];self.overlay(db,doc,local=True);capture=effective.capture(db);self.assertEqual(len(capture['inventory']),capture['base_inventory_count']+1);row=next(r for r in self.resolve(capture)['entries'] if r['entry_id']==doc['entry_id']);self.assertEqual(row['state'],'unknown');self.assertEqual(row['catalog_state'],'active')

def test_structured_field_override_changes_transitive_binding_hash(self):
 with tempfile.TemporaryDirectory() as td:
  db=self.fixture(pathlib.Path(td));before=effective.capture(db);binding=self.doc(db,'aidl:a.I#take(P)')['entry_id'];old=next(r for r in self.resolve(before)['entries'] if r['entry_id']==binding);doc=self.doc(db,'aidl:a.I.P#x');doc['return_type']['text']='long';self.overlay(db,doc);after=effective.capture(db);new=next(r for r in self.resolve(after)['entries'] if r['entry_id']==binding);self.assertEqual(new['state'],'available');self.assertNotEqual(old['schema_hash'],new['schema_hash']);self.assertNotEqual(before['inventory_sha256'],after['inventory_sha256']);self.assertEqual(after['overlay_generation'],before['overlay_generation']+1)

def test_suppressed_type_denies_an_otherwise_allowed_binding(self):
 with tempfile.TemporaryDirectory() as td:
  db=self.fixture(pathlib.Path(td));self.overlay(db,self.doc(db,'aidl:a.I.P'),'suppressed');captured=effective.capture(db);snapshot=self.resolve(captured);key=self.doc(db,'aidl:a.I#take(P)')['entry_id'];row=next(r for r in snapshot['entries'] if r['entry_id']==key);self.assertEqual(row['state'],'available');status=dict(snapshot=snapshot,stale=False,generation=1,capability_epoch=0);rule=policy_reference.Rule('allow',row['schema_hash'],frozenset({'platform:local'}),1);entry=policy_reference.Rule('allow','tool',frozenset({'platform:local'}),1);self.assertEqual(policy_reference.evaluate_view_fixture([(key,row['schema_hash'],'platform:local',1)],status,{key:rule},entry,entry_schema='tool',authority=True,current_document_hashes=captured['document_hashes']),'deny')
